60:   constructor(readonly code: string) { super(code); }
61: }
62: 
63: /** The owner must persist merge intent before calling this function. */
64: export async function requestExactMerge(adapter: PullRequestAdapter, request: ExactMergeRequest): Promise<PullRequestObservation> {
65:   if (!request.nativeId || request.nativeId.length > 256 || !validRevision(request.headRevision) ||
66:       !validBranchRef(request.baseRef) || !validRevision(request.baseRevision) ||
67:       !request.requiredHumanActorId) throw new PullRequestError("invalid_merge_request");
68:   const before = await adapter.read(request.repository, request.nativeId);
69:   if (!before) throw new PullRequestError("pr_missing");
70:   validateObservation(before, request.repository, request.nativeId);
71:   if (before.state === "merged") {
72:     if (before.head.revision === request.headRevision && before.mergedRevision === request.headRevision) return before;
73:     throw new PullRequestError("merge_identity_mismatch");
74:   }
75:   if (before.state !== "open") throw new PullRequestError("pr_closed");
76:   if (before.draft) throw new PullRequestError("draft_pr");
77:   if (before.queuedMerge === "queued") throw new PullRequestError("merge_already_queued");
78:   if (before.head.revision !== request.headRevision) throw new PullRequestError("head_moved");
79:   if (before.base.ref !== request.baseRef || before.base.revision !== request.baseRevision) {
80:     throw new PullRequestError("base_moved");
81:   }
82:   if (before.mergeStrategy !== request.strategy) throw new PullRequestError("strategy_unsupported");
83:   if (before.mergeable !== true) throw new PullRequestError(before.mergeable === false ? "merge_conflict" : "mergeability_unknown");
84:   if (before.requiredChecks.some((check) => check.state !== "success")) throw new PullRequestError("required_checks_incomplete");
85:   const approvals = new Map<string, PullRequestReview>();
86:   for (const review of before.reviews) {
87:     if (review.actor.kind !== "human") continue;
88:     const previous = approvals.get(review.actor.nativeId);
89:     if (previous && review.submittedAt === previous.submittedAt && review.nativeId !== previous.nativeId) {
90:       throw new PullRequestError("approval_ambiguous");
91:     }
92:     if (!previous || Date.parse(review.submittedAt) > Date.parse(previous.submittedAt)) {
93:       approvals.set(review.actor.nativeId, review);
94:     }
95:   }
96:   const current = [...approvals.values()].filter((review) => !review.dismissed && !review.stale &&
97:     review.headRevision === request.headRevision);
98:   if (approvals.get(request.requiredHumanActorId)?.decision !== "approved" ||
99:       !current.some((review) => review.actor.nativeId === request.requiredHumanActorId && review.decision === "approved") ||
