105:   catch { /* The provider may have committed the effect before the error. Reconcile by read. */ }
106:   let after: PullRequestObservation | null;
107:   try { after = await adapter.read(request.repository, request.nativeId); }
108:   catch { throw new PullRequestError("merge_outcome_unknown"); }
109:   if (!after) throw new PullRequestError("merge_outcome_unknown");
110:   validateObservation(after, request.repository, request.nativeId);
111:   if (after.state === "merged" && after.head.revision === request.headRevision &&
112:       after.mergedRevision === request.headRevision) return after;
113:   throw new PullRequestError("merge_outcome_unknown");
114: }
