116: export function validateObservation(value: PullRequestObservation, repository: RepositoryIdentity, nativeId: string): void {
117:   if (!sameRepository(value.repository, repository) || value.nativeId !== nativeId ||
118:       !sameRepository(value.head.repository, repository) || !sameRepository(value.base.repository, repository) ||
119:       !validBranchRef(value.head.ref) || !validBranchRef(value.base.ref) ||
120:       !validRevision(value.head.revision) || !validRevision(value.base.revision) ||
121:       !value.providerRevision || value.providerRevision.length > 256 ||
122:       (value.mergedRevision !== undefined && !validRevision(value.mergedRevision))) {
123:     throw new PullRequestError("invalid_provider_observation");
124:   }
125: }

